import java.util.Scanner;

public class Main {
    static final int MAXN = 250005;
    static long[] factorials = new long[MAXN];
    static long[] inv_factorials = new long[MAXN];
    static long[][] memo = new long[26][MAXN];
    static int total_n, max_kk, mod;

    static long power(long base, int exp) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = res * base % mod;
            base = base * base % mod;
            exp >>= 1;
        }
        return res;
    }

    static int getLowbit(int x) {
        return x & (-x);
    }

    static long solve(int level, int mask) {
        if (memo[level][mask] != -1) return memo[level][mask];
        if (mask == 0) {
            long res = factorials[total_n];
            for (int i = 1; i <= level; i++)
                res = res * (max_kk - i + 1) % mod;
            memo[level][mask] = res;
            return res;
        }
        long res = 0;
        int tmp_mask = mask - getLowbit(mask);
        for (int sub_mask = tmp_mask; sub_mask > 0; sub_mask = (sub_mask - 1) & tmp_mask)
            res = (res + inv_factorials[mask - sub_mask] * solve(level + 1, sub_mask)) % mod;
        res = (res + inv_factorials[mask] * solve(level + 1, 0)) % mod;
        memo[level][mask] = res;
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        total_n = sc.nextInt();
        max_kk = sc.nextInt();
        mod = sc.nextInt();

        long ans = power(max_kk, total_n);
        if (total_n % 2 == 1) {
            System.out.println(ans);
            sc.close();
            return;
        }

        for (int i = 0; i <= total_n; i++) {
            factorials[i] = 1;
        }
        for (int i = 1; i <= total_n; i++) {
            factorials[i] = factorials[i - 1] * i % mod;
        }

        inv_factorials[total_n] = power(factorials[total_n], mod - 2);
        for (int i = total_n; i > 0; i--) {
            inv_factorials[i - 1] = inv_factorials[i] * i % mod;
        }

        for (int i = 0; i <= 25; i++) {
            for (int j = 0; j <= total_n; j++) {
                memo[i][j] = -1;
            }
        }

        ans = (ans - solve(0, total_n) + mod) % mod;
        System.out.println(ans);
        sc.close();
    }
}
